```c
#include <DHT.h>

#define DHTPIN 2 // Pin that the DHT22 is connected to
#define DHTTYPE DHT22 // Type of DHT sensor

DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  // Read temperature and humidity from DHT22
  float temperature = dht.readTemperature();
  float humidity = dht.readHumidity();

  // Check if temperature and humidity readings are valid
  if (isnan(temperature) || isnan(humidity)) {
    Serial.println("Error reading from DHT22!");
    return;
  }

  // Print temperature and humidity readings to serial monitor
  Serial.print("Temperature: ");
  Serial.print(temperature);
  Serial.println("*C");
  Serial.print("Humidity: ");
  Serial.print(humidity);
  Serial.println("%");

  // Calculate and print calibration values
  float calibrationTemperature = 0; // Adjust this value to your known temperature reading
  float calibrationHumidity = 0; // Adjust this value to your known humidity reading

  float calibratedTemperature = (temperature - calibrationTemperature) / 1.0;
  float calibratedHumidity = (humidity - calibrationHumidity) / 1.0;

  Serial.print("Calibrated Temperature: ");
  Serial.print(calibratedTemperature);
  Serial.println("*C");
  Serial.print("Calibrated Humidity: ");
  Serial.print(calibratedHumidity);
  Serial.println("%");

  delay(2000);
}
```
