// constants
const G = 9.81; // acceleration due to gravity (m/s^2)
const L = 100; // length of the pendulum (pixels)
const θ0 = 0; // initial angle (radians)

// get the canvas element
const canvas = document.getElementById('pendulum-path');
const ctx = canvas.getContext('2d');

// initialize the pendulum's state
let θ = θ0; // current angle (radians)
let ω = 0; // current angular velocity (radians/second)
let t = 0; // current time (seconds)
let started = false;

// function to update the pendulum's state
function update() {
    if (started) {
        // update the angular velocity
        ω += (-G * Math.sin(θ) / L) * Math.PI / 180; // convert to radians

        // update the angle
        θ += ω;

        // update the time
        t += 0.01; // time step (seconds)

        // render the pendulum
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.beginPath();
        ctx.arc(L * 0.5, L * 0.5, L * 0.4, -θ, -θ + Math.PI * 2);
        ctx.stroke();
    }
}

